            hr, div_color = r, row[0]
            break
    if hr is not None:
        for c in range(w):
            if all(grid[r][c] == div_color for r in range(h)):
                vc = c
                break
    if hr is None or vc is None:
        return grid

    # Use the populated quadrant as a tile, and repeat it in each quadrant.
    r0, r1 = (0, hr) if hr else (hr + 1, h)
    c0, c1 = (vc + 1, w) if vc + 1 < w else (0, vc)
