        if r == hr:
            continue
        for c in range(w):
            if c == vc:
                continue
            out[r][c] = tile[(r if r < hr else r - hr - 1) % len(tile)][
                (c if c < vc else c - vc - 1) % len(tile[0])
            ]
    return out
