def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate full divider rows and columns.
    divider_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    divider_cols = [
        c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1
    ]

    # Split the grid into compartments separated by those lines.
    row_bands = []
    start = 0
    for r in divider_rows:
        if start < r:
            row_bands.append((start, r))
        start = r + 1
    if start < h:
        row_bands.append((start, h))

    col_bands = []
    start = 0
    for c in divider_cols:
        if start < c:
            col_bands.append((start, c))
        start = c + 1
    if start < w:
        col_bands.append((start, w))

    if not row_bands or not col_bands:
        return grid

    # Pick the compartment containing the most non-background cells.
    background = max(set(x for row in grid for x in row),
                     key=lambda x: sum(row.count(x) for row in grid))
    source = None
    best = -1
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            score = sum(grid[r][c] != background
                        for r in range(r0, r1) for c in range(c0, c1))
            if score > best:
                best = score
                source = (r0, r1, c0, c1)

    r0, r1, c0, c1 = source
    tile = [row[c0:c1] for row in grid[r0:r1]]
    out = [row[:] for row in grid]

    for br0, br1 in row_bands:
        for bc0, bc1 in col_bands:
            for r in range(br0, br1):
                for c in range(bc0, bc1):
                    out[r][c] = tile[(r - br0) % len(tile)][(c - bc0) % len(tile[0])]

