def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    background = max(counts, key=counts.get)

    divider_rows = [
        r for r, row in enumerate(grid)
        if len(set(row)) == 1 and row[0] != background
    ]
    divider_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]

    def bands(size, dividers):
        result, start = [], 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    rb = bands(h, divider_rows)
    cb = bands(w, divider_cols)
    if not rb or not cb:
        return grid

    # Choose the compartment with the most cells that are not background.
    source = max(
        ((r0, r1, c0, c1) for r0, r1 in rb for c0, c1 in cb),
        key=lambda box: sum(
            grid[r][c] != background
            for r in range(box[0], box[1])
            for c in range(box[2], box[3])
        )
    )
    r0, r1, c0, c1 = source
    tile = [row[c0:c1] for row in grid[r0:r1]]

    out = [row[:] for row in grid]
    for a, b in rb:
        for x, y in cb:
            for r in range(a, b):
                for c in range(x, y):
                    out[r][c] = tile[(r - a) % len(tile)][(c - x) % len(tile[0])]
    return out
